1	import { randomUUID } from "node:crypto";
2	import { trace } from "@opentelemetry/api";
3	import { tableNameFromSlug } from "../shared/slugify.js";
4	import { log } from "./log.js";
5	
6	const SPINE_URL = process.env.SPINE_URL || "http://localhost:4600";
7	
8	export const CARD_RETURNED_EVENT_NAME = "card.returned" as const;
9	
10	export interface CardReturnedParams {
11	  /** The Spine's real table id (the full slug), matching seat.joined's `entry.spineTableId`. */
12	  tableId: string;
13	  seatId: string;
14	  playerName: string;
15	  scryfallId: string;
16	  gameCardIndex: number;
17	  fromZone?: string;
18	}
19	
20	/**
21	 * Sends a `card.returned.v1` event to the Spine's generic events endpoint — the same send
22	 * shape `sendCardPlayedToSpineBestEffort` (Shuffler) already uses for `card.played`, and
23	 * `eventsUrl` is not introduced: the address is simply "the Spine". Rides the ambient
24	 * request/gesture span plus undici's automatic outbound `traceparent` header; no envelope
25	 * `traceparent` is minted here. Best-effort: never throws or rejects, so a Spine failure
26	 * never fails the caller's own action — on failure it sets `spine_send.send_failed` on the
27	 * active span and logs a warning. Like `HttpSpineGateway.sendEvent` (Shuffler), this uses a
28	 * bare `fetch` with no bounded timeout, so a Spine that accepts the connection but never
29	 * responds can still stall the caller for as long as Node's default fetch timeout (5 min) —
30	 * unlike `spineSubscriber.ts`'s long-lived SSE connection, this hasn't yet been given a
31	 * heartbeat-aware dispatcher.
32	 */
33	export async function sendCardReturnedToSpineBestEffort(params: CardReturnedParams, baseUrl: string = SPINE_URL): Promise<void> {
34	  const { tableId, seatId, playerName, scryfallId, gameCardIndex, fromZone } = params;
35	  const event = {
36	    id: randomUUID(),
37	    tableId,
38	    name: CARD_RETURNED_EVENT_NAME,
39	    occurredAt: new Date().toISOString(),
40	    initiator: { seatId, playerName },
41	    occurredIn: "tabletop" as const,
42	    origin: "tabletop.cardShapeHook",
43	    significance: "domain" as const,
44	    schemaVersion: 1,
45	    payload: {
46	      card: { scryfallId },
47	      gameCardIndex,
48	      seat: seatId,
49	      ...(fromZone !== undefined ? { fromZone } : {}),
50	    },
51	  };
52	
53	  try {
54	    const url = `${baseUrl}/tables/${encodeURIComponent(tableId)}/events`;
55	    const response = await fetch(url, {
56	      method: "POST",
57	      headers: { "content-type": "application/json" },
58	      body: JSON.stringify(event),
59	    });
60	    if (!response.ok) {
61	      const bodyText = await response.text().catch(() => "");
62	      throw new Error(`Spine rejected the event: ${response.status} ${response.statusText} ${bodyText}`.trim());
63	    }
64	  } catch (error) {
65	    trace.getActiveSpan()?.setAttributes({
66	      "spine_send.send_failed": true,
67	      "table.name": tableNameFromSlug(tableId),
68	      "table.slug": tableId,
69	    });
70	    log.warn(
71	      "card.returned send to Spine failed (best-effort; the drag gesture on the canvas proceeds regardless)",
72	      { "table.name": tableNameFromSlug(tableId), "table.slug": tableId },
73	      error
74	    );
75	  }
76	}
